-- READ-ONLY metadata inventory, not a migration, installer, readiness verdict,
-- full catalog diff, or authorization to deploy. Requires catalog visibility.
-- It reads no user/business rows and is intentionally limited to selected
-- finance objects. Privileges shown are effective SQL grants, NOT RLS access.
-- Compare complete target catalogs, data and clients separately; an empty
-- mismatch list does not mean the candidates can safely be installed.
WITH expected_columns(rel,col,typ) AS (VALUES
 ('users','id','uuid'),('users','email','text'),('users','role','text'),
 ('projects','id','uuid'),('project_supervisors','project_id','uuid'),('project_supervisors','supervisor_id','uuid'),('project_worker_assignments','project_id','uuid'),('project_worker_assignments','worker_id','uuid'),('project_worker_assignments','active','boolean'),
 ('workers','id','uuid'),('workers','name','text'),('workers','position','text'),('workers','pay_rate','numeric(10,2)'),('workers','pay_rate_type','text'),('workers','active','boolean'),
 ('attendance','id','uuid'),('attendance','worker_id','uuid'),('attendance','project_id','uuid'),('attendance','date','date'),('attendance','status','text'),('attendance','hours_worked','numeric(4,2)'),('attendance','submitted_at','timestamp with time zone'),
 ('payroll','id','uuid'),('payroll','worker_id','uuid'),('payroll','period_start','date'),('payroll','period_end','date'),('payroll','status','text'),('payroll','gross_pay','numeric(10,2)'),('payroll','bale_deduction','numeric(10,2)'),('payroll','other_deductions','numeric(10,2)'),('payroll','net_pay','numeric(10,2)'),('payroll','days_worked','numeric(5,2)'),('payroll','hours_worked','numeric(6,2)'),('payroll','notes','text'),
 ('advances','id','uuid'),('advances','worker_id','uuid'),('advances','project_id','uuid'),('advances','amount','numeric(10,2)'),('advances','amount_deducted','numeric(10,2)'),('advances','reason','text'),('advances','date','date'),('advances','status','text'),
 ('advance_requests','id','uuid'),('advance_requests','worker_id','uuid'),('advance_requests','project_id','uuid'),('advance_requests','requested_amount','numeric(10,2)'),('advance_requests','status','text'),('advance_requests','submitted_by','uuid'),('advance_requests','approved_by','uuid'),('advance_requests','approved_at','timestamp with time zone'),('advance_requests','rejected_by','uuid'),('advance_requests','rejected_at','timestamp with time zone'),('advance_requests','issued_by','uuid'),('advance_requests','issued_at','timestamp with time zone'),('advance_requests','issued_advance_id','uuid'),('advance_requests','created_at','timestamp with time zone'),('advance_requests','updated_at','timestamp with time zone'),
 ('expenses','id','uuid'),('expenses','project_id','uuid'),('expenses','description','text'),('expenses','category','text'),('expenses','amount','numeric(12,2)'),('expenses','expense_date','date'),('expenses','ai_bale_detection','boolean'),('expenses','revision','bigint'),
 ('audit_log','actor_id','uuid'),('audit_log','actor_email','text'),('audit_log','action','text'),('audit_log','table_name','text'),('audit_log','record_id','uuid'),('audit_log','before_row','jsonb'),('audit_log','after_row','jsonb')
), inventory_relations(rel) AS (VALUES ('users'),('workers'),('projects'),('project_supervisors'),('project_worker_assignments'),('attendance'),('payroll'),('advances'),('advance_requests'),('expenses'),('audit_log'),('supervisor_daily_attendance'),('supervisor_leave_requests')),
 new_relations(name) AS (VALUES ('public.weekly_worker_draft_sources'),('public.weekly_worker_paid_allocations'),('public.weekly_bale_requests'),('public.weekly_bale_expiry_health'),('public.supervisor_period_payroll'),('public.historical_external_worker_payroll'),('public.confirmed_rental_expenses')),
 functions(signature) AS (VALUES ('public.guard_payroll_finalized_fields()'),('public.set_payroll_status_atomic(uuid,text)'),('public.guard_advance_request_site()'),('public.audit_advance_request_change()'),('public.notify_advance_request_event()'),('public.bump_expense_revision()'),('public.weekly_worker_preview_inputs(date)'),('public.is_founder()'),('public.session_assurance_satisfied()')),
 roles(name) AS (VALUES ('anon'),('authenticated'),('service_role')),
 objects AS (SELECT i.rel,c.oid,c.relrowsecurity,c.relforcerowsecurity FROM inventory_relations i LEFT JOIN pg_catalog.pg_class c ON c.oid=pg_catalog.to_regclass('public.'||i.rel)),
 columns AS (SELECT e.*,a.attname,pg_catalog.format_type(a.atttypid,a.atttypmod) actual,a.attnotnull FROM expected_columns e LEFT JOIN objects o ON o.rel=e.rel LEFT JOIN pg_catalog.pg_attribute a ON a.attrelid=o.oid AND a.attname=e.col AND a.attnum>0 AND NOT a.attisdropped)
SELECT jsonb_build_object(
 'missing_roles',(SELECT coalesce(jsonb_agg(name ORDER BY name),'[]'::jsonb) FROM roles WHERE NOT EXISTS(SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname=roles.name)),
 'missing_relations',(SELECT coalesce(jsonb_agg(rel ORDER BY rel),'[]'::jsonb) FROM objects WHERE oid IS NULL),
 'missing_or_different_columns',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',rel,'column',col,'expected_type',typ,'actual_type',actual) ORDER BY rel,col),'[]'::jsonb) FROM columns WHERE attname IS NULL OR actual IS DISTINCT FROM typ),
 'candidate_relation_collisions',(SELECT coalesce(jsonb_agg(name ORDER BY name),'[]'::jsonb) FROM new_relations WHERE pg_catalog.to_regclass(name) IS NOT NULL),
 'column_properties',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',c.rel,'column',c.col,'type',c.actual,'not_null',c.attnotnull,'has_default',d.oid IS NOT NULL) ORDER BY c.rel,c.col),'[]'::jsonb) FROM columns c JOIN objects o ON o.rel=c.rel JOIN pg_catalog.pg_attribute a ON a.attrelid=o.oid AND a.attname=c.col AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=o.oid AND d.adnum=a.attnum),
 'relation_security',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',rel,'rls',relrowsecurity,'force_rls',relforcerowsecurity) ORDER BY rel),'[]'::jsonb) FROM objects WHERE oid IS NOT NULL),
 'effective_table_grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',o.rel,'role',r.name,'select',pg_catalog.has_table_privilege(r.name,o.oid,'SELECT'),'insert',pg_catalog.has_table_privilege(r.name,o.oid,'INSERT'),'update',pg_catalog.has_table_privilege(r.name,o.oid,'UPDATE'),'delete',pg_catalog.has_table_privilege(r.name,o.oid,'DELETE'),'truncate',pg_catalog.has_table_privilege(r.name,o.oid,'TRUNCATE')) ORDER BY o.rel,r.name),'[]'::jsonb) FROM objects o CROSS JOIN roles r JOIN pg_catalog.pg_roles actual_role ON actual_role.rolname=r.name WHERE o.oid IS NOT NULL),
 'explicit_column_grants',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',o.rel,'column',a.attname,'acl',a.attacl::text) ORDER BY o.rel,a.attnum),'[]'::jsonb) FROM objects o JOIN pg_catalog.pg_attribute a ON a.attrelid=o.oid AND a.attnum>0 AND NOT a.attisdropped WHERE a.attacl IS NOT NULL),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',o.rel,'name',c.conname,'type',c.contype,'validated',c.convalidated,'definition_md5',md5(pg_catalog.pg_get_constraintdef(c.oid))) ORDER BY o.rel,c.conname),'[]'::jsonb) FROM objects o JOIN pg_catalog.pg_constraint c ON c.conrelid=o.oid),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',o.rel,'name',t.tgname,'enabled',t.tgenabled,'definition_md5',md5(pg_catalog.pg_get_triggerdef(t.oid)),'function_body_md5',md5(p.prosrc)) ORDER BY o.rel,t.tgname),'[]'::jsonb) FROM objects o JOIN pg_catalog.pg_trigger t ON t.tgrelid=o.oid AND NOT t.tgisinternal JOIN pg_catalog.pg_proc p ON p.oid=t.tgfoid),
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',o.rel,'name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',p.polroles::text,'using_md5',md5(pg_catalog.pg_get_expr(p.polqual,p.polrelid)),'check_md5',md5(pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid))) ORDER BY o.rel,p.polname),'[]'::jsonb) FROM objects o JOIN pg_catalog.pg_policy p ON p.polrelid=o.oid),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('signature',f.signature,'exists',p.oid IS NOT NULL,'body_md5',md5(p.prosrc),'security_definer',p.prosecdef,'config',p.proconfig,'execute_grants',CASE WHEN p.oid IS NULL THEN NULL ELSE (SELECT coalesce(jsonb_object_agg(r.name,pg_catalog.has_function_privilege(r.name,p.oid,'EXECUTE')),'{}'::jsonb) FROM roles r JOIN pg_catalog.pg_roles ar ON ar.rolname=r.name) END) ORDER BY f.signature),'[]'::jsonb) FROM functions f LEFT JOIN pg_catalog.pg_proc p ON p.oid=pg_catalog.to_regprocedure(f.signature))
) AS inventory;
